ALTER POLICY admission_link_read_files ON storage.objects USING (bucket_id = 'admissao-uploads' AND EXISTS (SELECT 1 FROM public.admission_requests r WHERE split_part(name,'/',1) = 'requests' AND split_part(name,'/',2) = r.id::text AND app_security.admission_link_allows(r.id,false)));
ALTER POLICY admission_link_delete_files ON storage.objects USING (bucket_id = 'admissao-uploads' AND EXISTS (SELECT 1 FROM public.admission_requests r WHERE split_part(name,'/',1) = 'requests' AND split_part(name,'/',2) = r.id::text AND app_security.admission_link_allows(r.id,true)));
ALTER POLICY admissao_uploads_public_insert ON storage.objects WITH CHECK (bucket_id = 'admissao-uploads' AND EXISTS (SELECT 1 FROM public.admission_requests r WHERE split_part(name,'/',1) = 'requests' AND split_part(name,'/',2) = r.id::text AND app_security.admission_link_allows(r.id,true)));
CREATE POLICY admission_file_delete_draft_only ON public.admission_files AS RESTRICTIVE FOR DELETE TO public USING (app_security.internal_user_authorized() OR app_security.admission_link_allows(request_id,true));